from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];O=R/'qa/stage-light';html=(R/'dist/INK-Street-Fighter-6.html').read_bytes()
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page(viewport={'width':1440,'height':1100});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html.decode());p.wait_for_function('window.INKDuel?.ready');p.locator('.kinetic-launch button').click();p.locator('#fight-practice').click();p.evaluate('SVG_FIGHTER.state.paused=true')
 rows=[]
 for stage in ['neon','courtyard','rooftop']:
  p.locator('#stage-light-coach select').select_option(stage);p.evaluate("SVG_FIGHTER.render();INK.VFX.render(SVG_FIGHTER.state,1)")
  rows.append({'name':stage+' environment and body lighting mounted','passed':p.evaluate("s=>SVG_FIGHTER.state.stage===s&&INK.StageLight.inspect().actors===2&&INK.StageLight.inspect().fields===6",stage)})
  p.locator('#game').screenshot(path=str(O/(stage+'.png')))
 rows+=p.evaluate('''()=>{const A=SVG_FIGHTER,G=A.state,out=[],check=(name,passed,details)=>out.push({name,passed,details});A.setStage('neon');A.reset();G.paused=true;document.getElementById('dummy').value='idle';A.teleport(0,560);A.teleport(1,720);A.inputMove(0,'sHP');for(let i=0;i<80&&!INK.Kinetic.inspect().events.some(e=>e.type==='hit');i++)A.step();A.render();INK.VFX.render(G,1);check('Actual contact produces a bounded light field',INK.StageLight.sources(G).some(s=>s.power>0)&&INK.StageLight.sources(G).length<=6);check('Actor light uses a nonrecursive live-art mask',A.fighters.every(f=>{const n=f.inkRenderer.group.querySelector('[data-stage-body-light]'),m=f.inkRenderer.group.querySelector('mask');return n&&m?.querySelector('use')?.getAttribute('href')==='#'+f.inkRenderer.art.id&&!f.inkRenderer.art.contains(n);}));
 for(let i=0;i<3;i++){INK.Runtime.invalidate();A.render();INK.VFX.render(G,1);}check('Renderer edits rebuild exactly two body light rigs without stale masks',INK.StageLight.inspect().actors===2&&document.querySelectorAll('[data-stage-body-light]').length===2&&document.querySelectorAll('[data-foot-contact]').length===4);
 const before=JSON.stringify(A.fighters.map(f=>[f.hp,f.x,f.y,f.state,f.stateT])),time=INK.VFX.time;for(let i=0;i<25;i++){A.render();INK.VFX.render(G,1);}check('Repeated paused lighting draws preserve combat and light clock',time===INK.VFX.time&&before===JSON.stringify(A.fighters.map(f=>[f.hp,f.x,f.y,f.state,f.stateT])));check('Light feedback leaves the scene camera stable',!document.getElementById('camera').getAttribute('transform')||['matrix(1 0 0 1 0 0)','translate(0 0)'].includes(document.getElementById('camera').getAttribute('transform')),{camera:document.getElementById('camera').getAttribute('transform')});
 A.reset();G.paused=true;A.teleport(0,300);A.teleport(1,1100);A.render();const ground=+A.fighters[0].shadow.children[0].getAttribute('rx');A.press(0,'up');A.step(18);A.render();const f=A.fighters[0];check('Airborne fighter has a broader ground shadow and no planted foot shadow',+f.shadow.children[0].getAttribute('rx')>ground&&[...f.shadow.querySelectorAll('[data-foot-contact]')].every(n=>+n.getAttribute('opacity')===0));A.release(0,'up');
 INK.StageLight.settings.enabled=false;A.render();INK.VFX.render(G,1);check('Disabling restores original shadow dimensions and hides added lights',+f.shadow.children[0].getAttribute('rx')===107&&f.inkRenderer.group.querySelector('[data-stage-body-light]').getAttribute('display')==='none');INK.StageLight.settings.enabled=true;A.reset();G.paused=true;A.teleport(0,560);A.teleport(1,720);A.inputMove(0,'shoryu_1');A.step(13);A.render();INK.VFX.render(G,1);return out;}''')
 p.locator('#game').screenshot(path=str(O/'contact.png'));p.set_viewport_size({'width':390,'height':844});rows.append({'name':'Scene controls fit a narrow viewport','passed':p.locator('#stage-light-coach').evaluate('(e)=>e.getBoundingClientRect().right<=innerWidth+1')});b.close()
for r in rows:print('PASS' if r['passed'] else 'FAIL',r['name'],r.get('details',''))
(O/'playable.json').write_text(json.dumps({'htmlSha256':hashlib.sha256(html).hexdigest(),'rows':rows,'errors':errors},indent=2)+'\n');print(errors);assert all(r['passed'] for r in rows) and not errors
